import { office } from './office.js';
import facts from './municipality-facts.json';

/** Generated by scripts/build-municipality-data.mjs. */
export interface MunicipalityFacts {
	district: string;
	population: number;
	populationChangePercent: number;
	landAreaKm2: number;
	densityPerKm2: number;
	/** Nearest Environment Canada forecast site. */
	siteId: string;
	siteName: string;
}

export const municipalityFacts: Record<string, MunicipalityFacts> = facts;

type Census = Pick<
	MunicipalityFacts,
	'population' | 'populationChangePercent' | 'landAreaKm2' | 'densityPerKm2'
>;

/** The census figures for all the municipalities together. */
export function totalCensus(all: Iterable<Census>): Census {
	let population = 0;
	let population2016 = 0;
	let landAreaKm2 = 0;
	for (const entry of all) {
		population += entry.population;
		// The 2016 figure is worked back from the change, so the total change is weighted by size.
		population2016 += entry.population / (1 + entry.populationChangePercent / 100);
		landAreaKm2 += entry.landAreaKm2;
	}
	const round = (value: number) => Math.round(value * 10) / 10;
	return {
		population,
		populationChangePercent: round((population / population2016 - 1) * 100),
		landAreaKm2: round(landAreaKm2),
		densityPerKm2: round(population / landAreaKm2)
	};
}

/** What the panel shows for the office: the totals for every client, with Sudbury's weather. */
const officeFacts: MunicipalityFacts = {
	district: 'Sudbury office',
	...totalCensus(Object.values(municipalityFacts)),
	siteId: 'on-40',
	siteName: 'Greater Sudbury'
};

/** Facts for a municipality, or for the office when `name` is the office's. */
export function factsFor(name: string): MunicipalityFacts {
	return name === office.name ? officeFacts : municipalityFacts[name];
}
